import { date } from 'quasar';
import { dynamicObj } from './../../../pages/assets';
import { defineStore } from 'pinia';
import { asnApiService } from 'src/services';
export interface Props {
  data: AsnDataOrderDetail;
  loading: boolean;
  params: any;
}

interface AsnDataOrderDetail {
  customer_name: string;
  customer_number: string;
  customer_order_number: boolean;
  customer_po: string;
  line_status: string;
  order_date: any;
  ordered_quantity: number;
  otr: string;
  cpu: string;
  promised_delivery_date: string;
  requested_delivery_date: string;
  ship_to_location: any;
  shipped_quantity: number;
  status: string;
  warehouse_name: string;
  sales_person_name: string;
  whs: string;
  preview_path: string;
  OrderLines?: any;
}
export const useDashboardASNOrderDetail = defineStore(
  'dashboard_asn_order_detail',
  {
    state: (): Props => ({
      loading: true,
      data: {
        customer_name: '',
        customer_number: '',
        customer_order_number: false,
        customer_po: '',
        line_status: '',
        order_date: '',
        ordered_quantity: 0,
        otr: '',
        cpu: '',
        promised_delivery_date: '',
        requested_delivery_date: '',
        ship_to_location: '',
        shipped_quantity: 0,
        status: '',
        warehouse_name: '',
        sales_person_name: '',
        whs: '',
        preview_path: '',
      },
      params: null,
    }),
    actions: {
      async getAsnOrderDataDetail(params: any) {
        try {
          const response =
            await asnApiService.getAsnDashboardOrderDetail(params);

          if (!response) {
            throw response;
          }
          this.data = response.data;
        } catch (error) {
          throw error;
        }
      },
      async getAsnShareToken(id: any): Promise<any> {
        try {
          const response: dynamicObj =
            await asnApiService.getAsnShareTokenService(id);
          return response;
        } catch (error) {
          throw error;
        }
      },
      async getAsnPreview(params: number) {
        try {
          const response = await asnApiService.getAsnOrderPreview(params);
          if (!response || response.success == false) {
            throw response;
          }

          this.data.preview_path = response.data.preview_path;
        } catch (error) {
          throw error;
        }
      },
    },
  },
);
